from pathlib import Path
import hashlib, re, sys
root = Path(sys.argv[1]) if len(sys.argv) > 1 else Path('.')
p = root / 'shortfilm/index.html'
b = p.read_bytes()
s = b.decode('utf-8')
VERSION = '2026.10.26 · 企业收款与10账号双线经营版'
if VERSION in s:
    print('Already updated'); sys.exit(0)
sha = hashlib.sha1(b'blob '+str(len(b)).encode()+b'\0'+b).hexdigest()
if sha != 'c4d6e8b97628b29b14452dcda81ad10b7dd96c51':
    raise SystemExit('Source changed; reconcile before applying: '+sha)
def rep(a,b):
    global s
    if a not in s: raise ValueError('Missing expected text: '+a[:70])
    s=s.replace(a,b)
def section(k,v):
    global s
    s,n=re.subn(r'<section id="'+re.escape(k)+r'">.*?</section>',lambda m:v,s,count=1,flags=re.S)
    if n!=1: raise ValueError('Missing section '+k)
rep('管理层 / 内容 / 技术共读 · 更新2026.10.24','管理层 / 内容 / 财务共读 · 更新2026.10.26')
rep('国内流程先跑通，海外小样同步验证。保留原方案的主体收款、账号网络和首月计划，包含《反正也没时间活》案例、公司商业化路径与精品短剧内容团队招聘。','国内流程打底，海外至少10个账号同步布局。授权译制与分销争取较快回款，原创精品积累长期资产。按50条合格成片/日设计产线，把公司收款、平台资格、版权与实际利润逐项说清。')
rep('<strong>4个账号</strong><span>2 YouTube + 2 TikTok</span>','<strong>10个起</strong><span>5 YouTube + 5 TikTok</span>')
rep('<strong>2＋1人</strong><span>编导＋AI创作 / 剧情剪辑</span>','<strong>50条 / 日</strong><span>授权成片目标 · 待产线实测</span>')
rep('<strong>30天</strong><span>流程、样片与商业验证</span>','<strong>双线经营</strong><span>授权现金流 / 原创资产</span>')
rep('<a href="#entity">主体收款</a>','<a href="#entity">收款结论</a>')
rep('<a href="#accounts">账号</a>','<a href="#accounts">10账号</a><a href="#scale">50条产能</a>')
section('decision','''<section id="decision"><div class="heading"><span>01</span><h2>两条经营线：授权批量做现金流，原创精品做资产</h2></div><p class="lead">不再按4账号的小型原创工作室规划。按公司的至少10个账号、每日50条合格成片目标组织，但不把产量、播放和到账当成同一件事。</p><div class="grid"><article class="panel card"><div class="eyebrow">快线 / 授权经营</div><h3>批量译制＋分销/发行</h3><p>已有海外授权的剧集，批量完成转录、翻译、配音、字幕与剪辑，接入实际可结算的CPS、机构发行分账或付费译制订单。成熟模块直接压测，不必人为限制每天只做几条。</p><p class="small">先明确是推广片段权还是全片发行权。目标50条合格成片/日，收入须以对应合同、有效转化和结算为依据。</p></article><article class="panel card violet"><div class="eyebrow">长线 / 原创IP</div><h3>有短剧经验的主创做精品</h3><p>编导、AI创作师和剧情后期负责3–20分钟的故事、角色、镜头与声音。单独排产和核算，不背每天50部新原创的指标，不被批量翻译质检占满。</p><p class="small">现有技术组提供制作工具。这仍是内容团队，不招聘短剧播放平台开发者。</p></article></div><div class="notice green"><b>建议决策：</b>大陆公司先推进真实企业合作与对公收款；香港主体按长期自营需求评估，不为TK中视频奖励盲目注册。首批10账号＝授权经营8个＋原创品牌2个。</div><div class="panel"><h3>必须分开验证的四件事</h3><p><b>有权发行 → 计划准入 → 作品可计费 → 银行到账。</b>有版权不等于获原创奖励；有香港公司不等于符合海外个人资格；银行能收美元不等于已经加入YPP。</p><span class="refs"><a href="#s1">[1]</a><a href="#s4">[4]</a><a href="#s31">[31]</a><a href="#s33">[33]</a></span></div></section>''')
section('entity','''<section id="entity"><div class="heading"><span>04</span><h2>大陆公司还是香港公司？先看谁给你付款</h2></div><p class="lead">“TK中视频”在本页指Creator Rewards，不是国内西瓜/抖音中视频伙伴计划。公司为主要经营和资产主体；个人港卡不等于香港公司银行账户。</p><div class="grid three"><article class="panel card orange"><div class="eyebrow">结论一 / TK中视频奖励</div><h3>不能靠注册公司解决</h3><p>这是符合条件的个人类型账户的创作者奖励，不是拿营业执照直接参加的企业计划。<b>大陆公司和香港公司都不能替代个人、地区与原创资格。</b></p><span class="refs"><a href="#s33">[33]</a><a href="#s9">[9]</a></span></article><article class="panel card"><div class="eyebrow">结论二 / TK短剧发行与CPS</div><h3>先以大陆公司核验</h3><p>直接机构合作要看平台合同；第三方分销要看付款公司。<b>没有证据表明所有短剧分账都必须香港公司，也没有公开证据保证本公司一定可直接收。</b></p><span class="refs"><a href="#s8">[8]</a><a href="#s35">[35]</a></span></article><article class="panel card green"><div class="eyebrow">结论三 / YouTube</div><h3>大陆有付款渠道，准入另审</h3><p>Google的中国YouTube付款表列有电汇；组织账户按公司名付款。<b>收款不一律需要香港公司，但大陆不在当前YPP新申请地区名单。</b></p><span class="refs"><a href="#s31">[31]</a><a href="#s5">[5]</a><a href="#s2">[2]</a></span></article></div><div class="scroll-table"><table><thead><tr><th>实际收入</th><th>大陆公司对公</th><th>香港公司</th><th>要做的动作</th></tr></thead><tbody><tr><td>TikTok Creator Rewards</td><td>不能按企业报名/企业账户即享奖励的方式办理。</td><td>不能代替合格个人及所在地。</td><td>没有真实合格创作者与对应支付资格时，不把它列为公司保底。</td></tr><tr><td>TikTok Drama Center机构合作</td><td>本公司准入、大陆银行支持，仍需正式答复。</td><td>是否需要取决于具体合作和支付规则，不先假设必须。</td><td>先提交大陆公司资料，书面问主体、受益人、币种和账期。</td></tr><tr><td>发行商CPS、译制费、版权费</td><td>对方接受大陆公司签约且开户行接受真实交易来款时，按对公合同办理。</td><td>通常不因流量来自TK或YT就必需；看合同与渠道。</td><td>确认实际付款法人、授权范围、有效订单和扣回规则。</td></tr><tr><td>YouTube付款</td><td>中国地区有官方电汇支持；已获批中国组织付款资料按规则配置银行。</td><td>香港资料用匹配的银行，可作为真实境外经营配置。</td><td>先核验组织AdSense、付款地区、名称、银行与税务。</td></tr><tr><td>YouTube新申请YPP</td><td>这是地区/内容准入，不是银行卡问题。中国大陆不在当前名单。</td><td>香港在名单中，但注册证和IP不是获批保证。</td><td>实际经营结构、所在地和身份须符合平台要求，不能虚报。</td></tr></tbody></table></div><div class="notice amber"><b>不要把两张官方表混在一起：</b>中国地区支持YouTube电汇，说明有支付渠道；YPP开放地区不含中国大陆，说明新申请另有资格限制。付款表不是大陆新频道必过的证明，地区表也不是“中国银行一概收不到钱”的证明。</div><div class="panel"><h3>1. YouTube企业收款怎么配置</h3><p><b>真实合格的经营/收益主体 → 组织AdSense for YouTube → 公司名称付款资料 → 地区匹配的企业银行 → 财务对账。</b></p><p>Google明确：组织款项付给公司名称；电汇银行地区需与付款资料地区一致。建议使用公司同名对公账户，香港资料不混绑大陆卡，大陆资料也不随意混绑香港账户。向银行核对受益人英文名称、SWIFT、币种和来款凭证。</p><p><b>多个频道可以使用同一个AdSense for YouTube。</b>同一收款人不要创建多个重复账户；每个频道仍单独达到YPP条件。10个内容账号不等于10套公司或收款账户。</p><p class="small">个人AdSense不能直接切换账户类型为组织，应按平台正式迁移/关闭重建等指引处理。不要把第三方账户借给公司使用。</p><span class="refs"><a href="#s5">[5]</a><a href="#s6">[6]</a><a href="#s32">[32]</a></span></div><div class="panel"><h3>2. TK中视频奖励：不是国内卡与香港卡二选一</h3><p>TikTok官方项目介绍要求可用地区的个人类型账户，并强调原创；2026年Organization功能清单仍将Creator Rewards列为不可用。公司可做制作与运营，但不因此获得个人奖励的申请资格。</p><p>具体地区支持的支付服务、收款人身份、税务资料及是否接受某类钱包，应以该市场当前条款和实际收益后台为准。本轮官方英语付款帮助页抓取受限，<b>不承诺大陆企业银行、香港企业银行或某个公司PayPal一定能绑</b>。</p><p>真实合格创作者与公司之间的版权、劳务或收益分配，另按实际关系签约和纳税，不能借名或购买收益号来替代资格。</p><span class="refs"><a href="#s33">[33]</a><a href="#s9">[9]</a></span></div><div class="panel"><h3>3. TK短剧收入：平台分账和第三方佣金要分开</h3><p><b>Drama Center：</b>官网确认短剧机构发行、翻译、发布、广告分成及付费解锁等合作方向，但未公开足以保证本公司/银行被接受的清单。先用大陆公司核验，不替平台承诺。</p><p><b>CPS/发行合同：</b>观众在TK看到推广，不代表TikTok付款；实际可能由版权方或发行商支付有效订单佣金。看合同付款法人和银行接收要求。推广授权不自动包含整剧重配音、翻译或全片发行。</p><p class="small">RS Boost是官方CPS机制实例，其协议对重配音等改动有额外同意要求；不能把默认推广素材许可当作任意译制许可证。</p><span class="refs"><a href="#s8">[8]</a><a href="#s35">[35]</a></span></div><div class="notice green"><b>针对公司的建议：</b>现在先走大陆公司可获准的企业合同和收款路径。长期明确自营海外版权/YouTube，且平台与银行接受真实经营结构时，香港公司＋企业账户可以成为统一的境外业务主体；它的价值是规范经营和结算，不是绕过Creator Rewards或YPP规则。</div><details class="panel"><summary>决定注册香港公司前，确认这5项</summary><ol><li>实际做哪个收益计划、由哪家法律主体付款。</li><li>平台是否接受拟议的真实主体、地址、运营安排与授权。</li><li>企业银行开户及该类来款能否通过审查。</li><li>秘书、地址、周年申报、会计/审计及税务等持续安排。</li><li>与大陆制作公司的版权、服务及资金往来如何记账。</li></ol><p class="small">不是办好公司即可免税、自动获批或随意使用虚拟银行。法律、银行和税务事项由相关专业人员按实际结构确认。</p><span class="refs"><a href="#s21">[21]</a><a href="#s7">[7]</a></span></details><details class="panel"><summary>复制：向平台/发行商询问企业收款</summary><div class="copybox" id="payment-query">我们拟以中国大陆公司经营已取得海外授权的短剧译制、发行及原创短片，请书面确认：
1. 是否接受本大陆公司作为签约、认证和收款主体？
2. 是否支持同名大陆企业银行，所需币种、SWIFT、凭证和票据是什么？
3. 如不支持，限制在主体、实际经营地还是支付渠道？香港公司是否适用，还需哪些实际资料？
4. 合作是Drama Center分账、第三方CPS、译制交付还是其他计划？付款法律主体是谁？
5. 收入基数、扣费、退款、归因窗口和账期如何规定？
6. 许可是否覆盖海外语言、平台、多账号、翻译配音、全片或推广片段？
7. 能否先做一批合格交付和一次正式结算，再扩大到每天50条？</div><div class="buttons"><button data-copy-target="payment-query">复制收款问题</button></div></details><div class="notice">未完成：公司后台准入、Drama Center合同和实际银行到账。未知银行支持、费率与资格保持“待确认”，不为了给出肯定答案而编造。国内制作/海外播出许可与税务仍按具体内容和主体核定。</div></section>''')
rep('<section id="money"><div class="heading"><span>05</span><h2>3–20分钟的平台变现</h2></div>','<section id="money"><div class="heading"><span>05</span><h2>3–20分钟的平台变现</h2></div><div class="notice green">Creator Rewards、Drama Center机构分账、第三方CPS、YouTube广告是四种不同收入。授权经营不应只押注个人原创奖励；开通资格、计费内容、收款人分别核定。</div>')
rep('官方公告的新申请门槛为1,000订阅，加365天8,000小时或90天2,000万Shorts观看。既有成员的入门资格不受新门槛影响；另有Shorts持续分成条件，申请前再核验。','官方帮助页确认：2027年2月1日起，新申请仍需1,000订阅，观看门槛变为365天8,000小时或90天2,000万Shorts观看；既有YPP身份不因此取消。另有Shorts每月分成所需90天1,000万观看要求，低于条件不影响其他长视频收益。申请前再核验。')
section('content','''<section id="content"><div class="heading"><span>06</span><h2>批量译制是经营能力，原创精品是长期能力</h2></div><p class="lead">允许技术提高授权内容的产能，但先确认哪种作品和结果可以结算。</p><div class="grid"><article class="panel card"><h3>授权经营生产线</h3><ol><li>核验海外地域/语言/平台、翻译配音及商用权利，区分推广片段与完整剧集。</li><li>取得母版、原剧本/字幕和音轨，建立授权ID与期限。</li><li>批量转录、术语统一、语境翻译、配音字幕及合成。</li><li>技术QC、语言和内容审核，按批准语种/品牌排期。</li><li>对应交付单或推广链接，跟踪有效转化、结算、成本。</li></ol><p class="small">已有成熟流水线可直接做目标压力测试，不以人工小样限制技术产能；未经质检的输出不算合格成片。</p></article><article class="panel card violet"><h3>原创精品生产线</h3><ol><li>编导确定故事、人物目标、冲突与结局。</li><li>分镜和声音预演通过，再调用昂贵生成。</li><li>AI创作负责连续镜头、角色一致性和表演。</li><li>剧情后期负责节奏、混音和最终完成度。</li><li>复盘观众、成本与真实商业机会，沉淀角色与方法。</li></ol><p class="small">内容人才不开发平台；技术组为制作提供工具。</p></article></div><div class="notice amber"><b>去重的正确用途：</b>内部重复文件/任务检查、素材归并、语言版本管理、误发和重复扣费预防。对外内容用真实本地化与创作价值获得观众，不以镜像、裁切或变速躲避审核。</div><div class="notice red"><b>有许可≠一定获原创奖励。</b>YouTube明确二次利用审核独立于版权许可；批量同质内容也可能不适合创收。TikTok Creator Rewards强调原创。技术改变文件特征，不等于改变作者身份或收益资格。<span class="refs"><a href="#s4">[4]</a><a href="#s33">[33]</a></span></div><div class="panel"><h3>短期收入按优先级核验</h3><p><b>已有授权CPS：</b>验证有效订单与结算，利用现有素材和投流经验；未经同意不重配音。<br><b>已签机构发行：</b>按接受片库和合同测试语言、题材及分账。<br><b>付费译制订单：</b>按合格版本/分钟交付，约定返修与授权边界。<br><b>自营频道：</b>同时积累，但只有资格与内容获准后才核算广告收益。</p><p class="small">这是经营建议，不代表已拿到上述合作或保证快钱。哪条已有真实客户和合同，哪条先验证；没有合同就不把制作量等同应收收入。</p></div></section>''')
section('accounts','''<section id="accounts"><div class="heading"><span>09</span><h2>首批10个账号：5组内容定位 × 2个平台</h2></div><p class="lead">先按两个平台合计至少10个配置：授权经营8个、原创精品2个。扩展到每平台10个时，先验证语言、片库和运营能力，不自动加倍购置身份或收款账户。</p><div class="scroll-table"><table><thead><tr><th>内容定位示例</th><th>YouTube</th><th>TikTok</th><th>主要路线</th></tr></thead><tbody><tr><td>英语 / 情感剧情</td><td>1频道</td><td>1账号</td><td>授权译制与分销</td></tr><tr><td>英语 / 悬疑反转</td><td>1频道</td><td>1账号</td><td>独立题材/片库</td></tr><tr><td>西语 / 情感剧情</td><td>1频道</td><td>1账号</td><td>有许可和语言审校后运营</td></tr><tr><td>西语 / 悬疑反转</td><td>1频道</td><td>1账号</td><td>独立受众定位</td></tr><tr><td>英语 / 原创精品品牌</td><td>1频道</td><td>1账号</td><td>原创正片、预告及制作故事</td></tr><tr><td>合计</td><td><b>5个</b></td><td><b>5个</b></td><td><b>10个</b></td></tr></tbody></table></div><p class="small">英语/西语是建议，不是假定你们已有西语团队。无西语权利/审校就改成有资源的语言或其他清晰品牌。受众语言不等于账号注册地区。</p><div class="panel"><h3>公司资产台账</h3><p>每号记录平台ID、品牌、语言、真实主体/地区、管理员与恢复方式、素材授权范围、收益路径、审核状态和收款资料。公司资产、工作账号、操作设备和AdSense账户不是一一对应关系。</p><p>使用真实资料与正常验证；平台支持时配置角色权限及双重验证。10个频道的观看不合并达标，也不因共用AdSense而自动获得创收。不要创建重复AdSense、买老收益号或用新账号绕开处罚。</p><span class="refs"><a href="#s30">[30]</a><a href="#s32">[32]</a><a href="#s1">[1]</a></span></div><div class="notice green">公司可管理多个内容账号，但不要把同一平台的多个账号当作相同视频的机械复制出口。各号有明确定位与排期；创作者奖励、发行分账、CPS分别使用相应获准路径。</div></section>
<section id="scale"><div class="heading"><span>09A</span><h2>每天50条：合格输出，不是50笔收入</h2></div><p class="lead">尊重每日50条微短剧的产线目标。原剧数量、集数、语言版本、合格成片和上传次数分开统计；同片跨平台两次上传不是生产两部新剧。</p><div class="flow"><div><b>有权使用</b><p>母版、语言/地域/平台许可和到期日。</p></div><div><b>合格输出50条</b><p>翻译、音画和内容QC通过后入库。</p></div><div><b>按定位排期</b><p>不机械要求每号每日5条，也不为凑量重复发。</p></div><div><b>真实结算</b><p>按有效订单、合格交付或平台分账入账。</p></div></div><div class="panel" style="margin-top:16px"><h3>产能最容易漏算的是质检与返工</h3><p>50条×平均8分钟＝400分钟。仅看一遍需要<b>6小时40分钟</b>；平均20分钟则要<b>16小时40分钟</b>，还没加改稿、配音和发布。模型生成快不代表人工审核消失。</p><p>快线至少明确发行运营和本地化质检两个责任角色，可先借调人员；是否再补1–2人以真实工时决定。机器筛黑帧、音轨、字幕、重复文件和授权到期，人工承担语言及内容判断。</p><p>已有成熟流程直接测试50条；未稳定的模块按10→25→50逐级验证。这是工程吞吐测试，不是养号频率或平台安全上限。</p></div><div class="panel"><h3>用合同收入公式决定扩量</h3><p><b>净贡献＝确认净收入－完整制作成本－投流－退款/扣回－其他约定费用。</b></p><p>假设50条/日、完整制作成本20元/条，即1,000元/日；30个生产日共3万元。再假设每个有效转化净结算10元，每天100个有效转化只覆盖制作成本，广告等未计入时还不是净利润。</p><p class="small">20元与10元是演示假设，不是报价。版权、人工、生成失败、翻译审校、算力/软件和存储分摊计入完整成本；不要用自己消耗时间未计价制造高利润。</p></div><div class="notice">已经能批量制作，可以同步经营，不必只等原创精品。但首笔平台/发行商结算应尽早验证；账期未到记应收，不记到账。单纯追求去重成功和播放截图，不等于商业验证。</div></section>''')
section('month','''<section id="month"><div class="heading"><span>12</span><h2>首月：10账号落地，授权快线与原创同步跑</h2></div><p class="lead">国内共用流程打底，海外先启动已具备权利和真实结算路径的项目，不等国内全部完工；尚未获批的渠道不伪装已开通。</p><div class="scroll-table"><table><thead><tr><th>阶段</th><th>授权经营</th><th>原创精品</th><th>经营验收</th></tr></thead><tbody><tr><td>第1周</td><td>10账号台账、片库/语种授权、现有产线压测</td><td>主创确定选题、大纲与关键分镜</td><td>确认谁付款、公司主体、银行、收入基数和账期</td></tr><tr><td>第2周</td><td>质检/授权通过后冲50条合格产能；按计划分发</td><td>首片预演、人物场景与镜头小样</td><td>实际交付/接收记录、有效转化与成本可追踪</td></tr><tr><td>第3周</td><td>扩大已验证片库和渠道，不强制各号同量</td><td>精修首部成片和预告</td><td>退款、待结算和实际订单分开记账</td></tr><tr><td>第4周</td><td>放大净贡献好的组合，暂停低效语种/片库</td><td>依据反馈打磨下一部和系列方向</td><td>对账与回款；未到期款项只计应收</td></tr></tbody></table></div><div class="grid"><article class="panel card green"><h3>快线考核</h3><p>合格成片量、完整单位成本、质量退回率、人工处理时间、有效转化、净贡献及到账。上传量和去重通过率不能替代结算。</p></article><article class="panel card violet"><h3>原创考核</h3><p>故事和成片质量、留存/回访、单片成本、角色资产和真实商业机会。不要用快线的50条产量约束原创编导。</p></article></div></section>''')
